      "synopsis": "Tras su salida de prisión, donde cumplió una condena de siete años por conducir su motocicleta en un robo fallido, Federico regresa a su decadente pueblo natal. Las cosas no han cambiado mucho: su madre lo adora, su padrastro desconfía de él y su hermano Ramiro sigue metido en negocios turbios. A pesar de sus esfuerzos, Federico termina por ceder a la tentación de correr motocicletas de nuevo y organiza una carrera contra un gangster local para saldar las deudas de su hermano. Sin embargo, Ramiro arregla la carrera a espaldas de Federico y desata así una cadena de sucesos que obligará a Federico a ir hasta las últimas consecuencias para proteger a su familia.",
