      "synopsis": "En Ciudad Academia, donde las habilidades sobrenaturales forman parte de la ciencia cotidiana, la paz de la ciudad se mantiene gracias a una fuerza invisible: el lado oscuro. Entre los agentes secretos se encuentra ITEM, una unidad de élite de cuatro miembros. Con las habilidades de rastreo de Rikou Takitsubo, la pericia en explosivos de Frenda Seivelun, la defensa impenetrable de Saiai Kinuhata y el poder abrumador de Shizuri Mugino, una de las siete espers de Nivel 5 de Ciudad Academia, se mueven por los bajos fondos de la ciudad, llevando a cabo misiones secretas que nunca llegan a los titulares. A medida que se desarrolla su última misión, el equipo actúa con precisión, sin saber que sus acciones están preparando el terreno para una tragedia que pondrá a prueba sus lazos de confianza, amistad y supervivencia en la implacable oscuridad de Ciudad Academia.",
