      "synopsis": "Serie Anime de 170 episodios. Black Clover sigue la historia de dos chicos, Asta y Yuno, que crecen en un orfanato de la iglesia de Hage, ubicada en el Reino del Trébol. Ambos se han criado en un mundo donde todas las personas tienen la habilidad de manipular el Poder Mágico. Todo menos Asta. Pero esto no le detendrá para convertirse en un Caballero Mágico al igual que Yuno al cumplir los 15 años. Yuno conseguirá el grimorio de un trébol de cuatro hojas, objeto que ayuda canalizar la magia del viento. Sin embargo, Asta no recibe ninguno. Ambos intentarán convertirse en el nuevo Rey Mago.",
