      "actors": "—",
      "synopsis": "Kurumi Fukuka es una estudiante universitaria que decide debutar en el mercado de divisas (FX) para recuperar los 20 millones de yenes (unos 126.000 dólares) que su difunta madre perdió en ese mismo mercado. Convencida de que será fácil recuperar el dinero, se lanza de lleno a un mundo donde todo puede pasar del cielo al infierno en un instante. Pérdidas no realizadas, ventas para cortar pérdidas, un corazón que no deja de latir acelerado… y aun así, Kurumi quiere comprar, vender y ganar. A su alrededor se reúnen otros “luchadores del FX”, y el mercado se vuelve cada vez más frenético. Mientras los gráficos suben y bajan sin parar, Kurumi continúa jugando a este juego del dinero, tan adorable como ligeramente peligroso. ¿Podrán ella y sus amigos sobrevivir en este mundo tan feroz?",
