      "synopsis": "En el centro de un continente formado por ocho reinos se ubica el Reino de Marronnier, una nación rodeada por siete países vecinos con los que ha mantenido una tensión política durante décadas. Para fortalecer los lazos diplomáticos y preservar la paz, la generala Baribara envía a sus siete hijos (cada uno con apodos y talentos únicos como insomne, bondadoso, sensible al calor, sensible al frío, domador, experto en espadas y hambriento) en misiones como embajadores hacia los reinos colindantes. Aunque los hermanos poseen personalidades muy diversas, comparten un gran objetivo en común: \"¡Algún día rescataremos a una princesa de una forma genial!\" Mientras viajan, se enfrentan a desafíos culturales e intrigas políticas, descubriendo misterios sobre los orígenes de su madre. En paralelo, la princesa de Marronnier escapa del palacio en secreto —disfrazada bajo el nombre de Bruno— para unirse al viaje de uno de los hermanos.",
