      "synopsis": "Sinbad: La leyenda de los siete mares, Acusado por error de haber robado el Libro de la Paz, el audaz y legendario Simbad tendrá que recuperar y restituir la valiosa obra, si no quiere que Proteo, su mejor amigo, encuentre la muerte. El aventurero rechaza la misión y opta por irse de crucero y a tomar el sol en las islas Fidji. ¡Pero no tan deprisa! Porque la bella prometida de Proteo, Marina, se ha colado a bordo del barco de Simbad para asegurarse de que cumple la misión, y el primer chico malo de la historia va a tener que enfrentarse a un increíble aluvión de peligros. Eris, Diosa del Caos, se ensaña con Simbad, arrojando contra él una jauría de monstruos y desencadenando terribles tempestades para impedir que llegue al Tártaro. Pero todos estos desafíos no serán nada comparados con lo que nuestro héroe tendrá que soportar a causa de la delicada pero temible Marina…",
      "kind": "película",
