      "synopsis": "El show de Snoopy Temporada 2 es una nueva serie animada para niños y familias protagonizada por el beagle amado internacionalmente y su mejor amigo emplumado Woodstock mientras abordan todas las nuevas aventuras. Snoopy puede parecer solo un cachorro que baila feliz, ama los huesos y se sienta en la casa del perro, pero es mucho más que eso. Él es Joe Cool: el chico más moderno de la escuela. Es el rey de los surfistas y el famoso luchador de brazos Masked Marvel. Él es Flying Ace de la Primera Guerra Mundial que lucha contra el Barón Rojo. Todas sus audaces y queridas personalidades se exhiben por completo en esta nueva comedia animada.",
