      "synopsis": "La acción tiene lugar en la Edad de Piedra,en un pueblo llamado Piedradura (“Bedrock”), pero presenta una sociedad idéntica a la americana de mediados del siglo pasado. En un mundo fantástico los dinosaurios, los tigres dientes de sable, los mamuts y otros animales hoy extintos coexistían con los hombres. La tecnología es similar a la del siglo XX, pero son animales los que sustituyen a los aparatos eléctricos. Los personajes conducen automóviles formados por troncos de madera (troncomóviles), ruedas de piedra, en los que el motor era sustituido por el empuje de los pies de sus ocupantes. Las vestimentas eran de piel animal.",
